import sys
import pandas as pd
import re

raw = ''.join(c for c in sys.stdin.read() if c.isprintable() and ord(c) < 128)
tokens = [t.strip() for t in re.split(r'[\,\s]+', raw) if t.strip()]

if tokens and len(tokens) >= 4:
    marks_list = []
    for t in tokens[:4]:
        if t.lower() in ('none', 'null', 'nan', 'na'):
            marks_list.append(None)
        else:
            try:
                marks_list.append(float(t))
            except ValueError:
                marks_list.append(None)
else:
    marks_list = [85.0, None, 78.0, 92.0]

students = pd.DataFrame({
    "ID": [101, 102, 103, 104],
    "Name": ["Arun", "Priya", "Rahul", "Meena"]
})

marks = pd.DataFrame({
    "ID": [101, 102, 103, 104],
    "Mark": marks_list
})

print("Missing values")
print(marks.isna().sum())

marks["Mark"] = marks["Mark"].fillna(0)

merged = pd.merge(students, marks, on="ID")

print("Final DataFrame")
print(merged)

print("Summary")
print(f"Total Students: {len(merged)}")
print(f"Total Marks: {merged['Mark'].sum()}")
